<thead>
<tr>
<th>Prop</th>
<th>Type</th>
<th>Default</th>
<th>Description</th>
</tr>
</thead>
<tbody>
<tr>
<td><code>as</code></td>
<td><code>ValidConstructor</code></td>
<td><code>'div'</code></td>
<td>Element or component to render as.</td>
</tr>
<tr>
<td><code>value</code></td>
<td><code>V</code></td>
<td><em>required</em></td>
<td>Must match the <code>value</code> of its <code>Tab</code>.</td>
